/* Product sizes and editable collections. Existing black/beige IDs are preserved. */
let collections=read('collections',[{id:'black',name:'جمال الأسود',description:'أناقة لا يغيّرها الوقت',imageKey:'category-black'},{id:'beige',name:'هدوء الألوان',description:'درجات طبيعية… وحضور مختلف',imageKey:'category-beige'}]);
const productSizes=p=>Array.isArray(p.sizes)?p.sizes:['S','M','L','XL','XXL'];
const collectionName=id=>collections.find(c=>c.id===id)?.name||'بدون تشكيلة';
function saveCollections(){try{localStorage.setItem('abayat-collections',JSON.stringify(collections));return true}catch{toast('تعذر حفظ التشكيلات في المتصفح');return false}}
function collectionOptions(selected){return `<option value="uncategorized" ${selected==='uncategorized'?'selected':''}>بدون تشكيلة</option>`+collections.map(c=>`<option value="${esc(c.id)}" ${selected===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}
function collectionCards(){return collections.slice(0,6).map(c=>`<a href="#shop/${c.id}" class="category">${mediaImage(c.imageKey,c.name)}<h3>${esc(c.name)}</h3><p>${esc(c.description)} ←</p></a>`).join('')}
function collectionToolbar(){return `<div class="toolbar"><a class="button outline" href="#shop">الكل</a>${collections.map(c=>`<a class="button outline" href="#shop/${c.id}">${esc(c.name)}</a>`).join('')}${products.some(p=>p.category==='uncategorized')?'<a class="button outline" href="#shop/uncategorized">بدون تشكيلة</a>':''}</div><br>`}
function catalogueAdminPage(){const visible=collections.filter(c=>c.name.includes(adminQuery)),paged=paginate(visible,'collections',20);return `<div class="page-title"><div><h1>التشكيلات</h1><p>نظّمي منتجاتك في تشكيلات تناسب متجرك.</p></div><button class="button" onclick="editCollection()">+ إضافة تشكيلة</button></div><div class="catalogue-grid">${paged.items.map(c=>`<article class="dashboard-panel catalogue-card">${mediaImage(c.imageKey,c.name)}<div><h2>${esc(c.name)}</h2><p class="catalogue-note">${products.filter(p=>p.category===c.id).length} منتجات</p><button class="text-button" onclick="editCollection('${c.id}')">تعديل</button><button class="text-button" onclick="editImage('${c.imageKey}')">الصورة</button><button class="text-button danger" onclick="confirmRemoveCollection('${c.id}')">حذف</button></div></article>`).join('')}</div>${paged.controls}${!visible.length?'<div class="empty">لا توجد تشكيلات مطابقة. أضيفي تشكيلة جديدة.</div>':''}<p class="catalogue-note">تُحدّد المقاسات المتاحة داخل تعديل كل منتج. لكل مقاس كمية مستقلة، وإجمالي المنتج يساوي مجموع كميات المقاسات.</p>`}
function editCollection(id){const c=collections.find(c=>c.id===id)||{name:'',description:''};modal(`<h2>${id?'تعديل التشكيلة':'تشكيلة جديدة'}</h2><form onsubmit="submitCollection(event,'${id||''}')"><label class="field">اسم التشكيلة<input name="name" required maxlength="50" value="${esc(c.name)}"></label><label class="field">وصف قصير<input name="description" maxlength="100" value="${esc(c.description)}"></label><p class="form-error" role="alert"></p><button class="button full">حفظ التشكيلة</button></form>`)}
function submitCollection(e,id){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.name=data.name.trim();data.description=data.description.trim();if(!data.name){e.target.querySelector('.form-error').textContent='اكتبي اسم التشكيلة.';return}if(collections.some(c=>c.id!==id&&c.name===data.name)){e.target.querySelector('.form-error').textContent='اسم التشكيلة موجود بالفعل.';return}if(id)Object.assign(collections.find(c=>c.id===id),data);else{const key='c-'+crypto.randomUUID();collections.push({...data,id:key,imageKey:'category-'+key})}saveCollections();$('#modal').close();render(false);toast('تم حفظ التشكيلة')}
function confirmRemoveCollection(id){const c=collections.find(c=>c.id===id);if(!c)return;const count=products.filter(p=>p.category===id).length;modal(`<h2>حذف ${esc(c.name)}؟</h2><p>${count?'سيتم نقل '+count+' منتجات إلى «بدون تشكيلة». لن يُحذف أي منتج.':'هذه التشكيلة لا تحتوي على منتجات.'}</p><button class="button" onclick="removeCollection('${id}')">حذف التشكيلة ونقل منتجاتها</button><button class="button outline" onclick="$('#modal').close()">إلغاء</button>`)}
function removeCollection(id){collections=collections.filter(c=>c.id!==id);for(const p of products)if(p.category===id)p.category='uncategorized';saveCollections();save();$('#modal').close();render(false);toast('تم حذف التشكيلة مع الاحتفاظ بمنتجاتها')}
const oldImageSlots=imageSlots;
imageSlots=()=>{const defaults=oldImageSlots().filter(s=>!s.key.startsWith('category-'));return [...defaults,...collections.map(c=>({key:c.imageKey,title:'تشكيلة '+c.name,type:'site',note:'بطاقة التشكيلة',ratio:'wide'}))]};
const beforeCatalogueRender=render;
render=function(scroll=true){beforeCatalogueRender(scroll);const nav=document.querySelector('body>nav');if(nav){nav.innerHTML=`<a href="#home">الرئيسية</a><a href="#shop">العبايات</a>${collections.slice(0,6).map(c=>`<a href="#shop/${c.id}">${esc(c.name)}</a>`).join('')}<a href="#favorites">المفضلة</a><a href="#orders">طلباتي</a>`}};
